from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for i, row in enumerate(grid):
        pattern = [j for j, value in enumerate(row) if value != background]
        if not pattern:
            continue
        n = len(pattern)
        candidates = []
        for k, source in enumerate(grid):
            if k == i:
                continue
            source_pattern = [j for j, value in enumerate(source) if value != background]
            if len(source_pattern) <= n or 2 * n < len(source_pattern):
                continue
            if all(source[j] == row[j] for j in pattern):
                candidates.append((len(source_pattern), k))
        if candidates:
            _, k = max(candidates)
            for j, value in enumerate(grid[k]):
                if value != background and row[j] == background:
                    out[i][j] = 1
    return out
